_COUNTRY_LENGTHS = {
    "AD": 24,
    "AT": 20,
    "BE": 16,
    "CH": 21,
    "DE": 22,
    "ES": 24,
    "FR": 27,
    "GB": 22,
    "IE": 22,
    "IT": 27,
    "LU": 20,
    "NL": 18,
    "NO": 15,
    "PL": 28,
    "PT": 25,
    "SE": 24,
}


def normalize_iban(iban: str) -> str:
    if not isinstance(iban, str):
        raise ValueError("iban must be a string")
    return iban.replace(" ", "").upper()


def validate_iban(iban: str) -> bool:
    if not isinstance(iban, str):
        return False
    normalized = iban.replace(" ", "").upper()
    if len(normalized) < 4:
        return False
    if not ("A" <= normalized[0] <= "Z" and "A" <= normalized[1] <= "Z"):
        return False
    if not ("0" <= normalized[2] <= "9" and "0" <= normalized[3] <= "9"):
        return False
    for ch in normalized[4:]:
        if not (("A" <= ch <= "Z") or ("0" <= ch <= "9")):
            return False
    expected = _COUNTRY_LENGTHS.get(normalized[:2])
    if expected is None:
        return False
    if len(normalized) != expected:
        return False
    rearranged = normalized[4:] + normalized[:4]
    remainder = 0
    for ch in rearranged:
        if "0" <= ch <= "9":
            remainder = (remainder * 10 + (ord(ch) - 48)) % 97
        else:
            value = ord(ch) - 55
            remainder = (remainder * 10 + value // 10) % 97
            remainder = (remainder * 10 + value % 10) % 97
    return remainder == 1
